item.aggregated_output:
\end{equation*}
where addition and multiplication are over $\Fq$.
For all $W \in \{X,Z\}$, $a, a' \in \Fq$, and $b \in \Fp$, powers of these
observables obey the relations
\begin{equation*}\label{eq:pauli-product-power}
  \bigl(\qp^W(a)\qp^W(a')\bigr) = \qp^W(a+a') \qquad \text{and}
  \qquad \bigl( \qp^W(a) \bigr)^b = \qp^W(a b) \;.
\end{equation*}
In particular, since $pa=0$ for any $a\in \Fq$ we get that that $(\qp^W(a))^p =
I$ for any $a\in\Fq$.
The observables obey analogous ``twisted commutation'' relations
to~\eqref{eq:twisted-fp},
\begin{equation}
  \label{eq:twisted-fq}
  \forall a, b \in \Fq\;, \qquad \qp^X(a)\, \qp^Z(b) =
  \omega^{-\tr(a b)} \, \qp^Z(b)\, \qp^X(a)\;.
\end{equation}
It is clear from the definition that all of the $\qp^X$ operators commute with
each other, and similarly all the $\qp^Z$ operators commute with each other.
Thus, it is meaningful to speak of a common eigenbasis for all $\qp^X$
operators, and a common eigenbasis for all $\qp^Z$ operators.
The common eigenbasis for the $\qp^Z$ operators is the computational
basis $\{\ket{j}\}_{j \in \F_q}$.
To map this basis to the common eigenbasis of the $\qp^X$ operators, one can
apply the Fourier transform
\begin{equation}
  \label{eq:fourier-f}
  F \,=\, \frac{1}{\sqrt{q}} \sum_{a, b\in \Fq} \omega^{-\tr(ab)}
  \ket{a}\bra{b}\;.
\end{equation}
Explicitly, the eigenbases consist of the vectors $\ket{e_W}$ labeled by an
element $e \in \Fq$ and $W \in \{X, Z\}$, given by
\begin{equation*}
  \ket{e_X} = \frac{1}{\sqrt{q}} \sum_j \omega^{- \tr(e j)} \ket{j}\;, \qquad
  \ket{e_Z}   = \ket{e}\;.
\end{equation*}
We denote the POVM whose elements are projectors onto basis vectors of the
eigenbasis associated with the observables $\qp^W$ by $\{\qp^W_e\}_e$.
Then for all $W \in \{X,Z\}$ and $a\in \Fq$, the observables $\qp^W(a)$ can be
written as
\begin{equation}\label{eq:pauli-obs-proj-single}
  \qp^W(a) = \sum_{b \in \Fq} \omega^{\tr(a b)} \qp^W_b\;.
\end{equation}

To invert this relation, we first quote the following useful Fourier fact.
\begin{lemma}[Fact 3.2 of \cite{NW19}]
  \label{lem:cancellation}
  Let $V$ be a subspace of $\F^k$. For all $v \not\in V^\perp$, 
  \begin{equation*}
    \E_{u \sim V} \omega^{\tr(u \cdot v)} = 0\;,
  \end{equation*}
  where the expectation is over a uniformly random vector $u$ from $V$.
\end{lemma}

We may now invert~\Cref{eq:pauli-obs-proj-single}:
\begin{equation}\label{eq:pauli-inversion-0-single}
  \E_{a\in \F_q} \omega^{-\tr(ab)} \qp^W(a) = \sum_{b'\in \F_q} \E_{a\in \F_q}
  \omega^{\tr(a(b'-b))} \qp^W_{b'} = \qp^W_b\;,
\end{equation}
where the second step follows from Lemma~\ref{lem:cancellation}.

For systems with many qudits, we will consider tensor products of the operators
$\qp^W$.
Slightly abusing notation, for $W \in \{X, Z\}$ and $a \in \Fq^n$ we denote by
$\qp^W(a)$ the tensor product $\qp^W(a_1) \ot \dots \ot \qp^W(a_n)$.
These obey the twisted commutation relations
\begin{equation*}
  \forall a,b\in \Fq^n,\qquad \qp^X(a)\, \qp^Z(b) \,=\, \omega^{-\tr (a \cdot
    b)}\, \qp^Z(b)\, \qp^X(a)\;,
\end{equation*}
where $a \cdot b = \sum_{i=1}^{n} a_i b_i \in \Fq$.
For $W\in\{X,Z\}$ and $e \in \Fq^n$ define the eigenstates
\[ \ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}\;, \]
and associated rank-$1$ projectors $\qp^W_e$. Analogous versions of \Cref{eq:pauli-obs-proj-single}
and \Cref{eq:pauli-inversion-0-single} relate the multi-qubit observables
and projectors:
\begin{align}
  \qp^W(a) &= \sum_{b \in \Fq^n} \omega^{\tr(a \cdot b)}
  \qp^W_b\;, \label{eq:pauli-obs-proj} \\
    \E_{a\in \F_q^n} \omega^{-\tr(a \cdot b)} \qp^W(a) &= \sum_{b'\in \F_q^n} \E_{a\in \F_q^n}
  \omega^{\tr(a\cdot (b'-b))} \qp^W_{b'} = \qp^W_b\;. \label{eq:pauli-inversion-0}
\end{align}

Since we only consider finite fields $\F_q$ such that $q = 2^k$ the maximally
entangled state $\ket{\EPR_q}$ and the corresponding qudit Pauli
observables/projectors are isomorphic to a tensor product of maximally entangled
states $\ket{\EPR_2}$ and \emph{qubit} Pauli observables/projectors
respectively; this is shown in the next lemma.
This is used to argue that the Pauli basis test (described in
Section~\ref{sec:pauli-verifier}) gives a self-test for Pauli observables and
maximally entangled states over qubits.

\begin{lemma}
  \label{lem:pauli-binary}
  For all admissible field sizes $q = 2^k$ and integers $L$, there exists
  an isomorphism $\phi: (\C^q)^{\otimes L} \to (\C^2)^{\otimes L k}$
  such that\footnote{ Here we have applied the natural identifications between
  $(\C^q)^{\ot L} \ot (\C^q)^{\ot L}$ and $(\C^q \ot \C^q)^{\ot L}$,
  and between $(\C^2)^{\ot L k} \ot (C^2)^{\ot Lk}$ and $(\C^2 \ot
  \C^2)^{\ot Lk}$.}
\begin{equation}
    \label{eq:epr-q-to-epr-2}
    \phi \otimes \phi \, \ket{\EPR_q}^{\otimes L} =
    \ket{\EPR_2}^{\otimes L k}\;.
  \end{equation}
  Moreover, for all $W \in \{X,Z\}$ and for all $u \in \F_q^L$
	\begin{equation}
	\label{eq:pauli-q-to-pauli-2}
  	\tau^W_u = \phi^\dagger\, \Bigl (\bigotimes_{i=1}^L
    \bigotimes_{j=1}^{k} \sigma^{W}_{u_{ij}} \Bigr) \, \phi\;.
	\end{equation}
	Here, the $(u_{ij})_{i,j}$ denotes a vector of $\F_2$ values such that $u_i =
  \sum_j u_{ij} e_j$ for all $i \in \{1,\ldots,L\}$ with
  $\{e_1,\ldots,e_{k}\}$ being the self-dual normal basis of $\F_q$ over $\F_2$
  specified by Lemma~\ref{lem:efficient_basis}.
  For $i\in\{1,\ldots,L\}$ and $j\in\{1,\ldots,q\}$ the $(i,j)$-th factor
  $\sigma^{W}_{u_{ij}}$ denotes the projector $\frac{1}{2} \left ( \Id +
    (-1)^{u_{ij}} \sigma^W(1) \right)$ acting on the $s$-th qubit of
  $\ket{\EPR_2}^{\otimes L k}$, where $s = (i-1) k + j$.
\end{lemma}

\begin{proof}
Define the isometry $\theta : \C^q \to (\C^2)^{\otimes k}$ as $\theta\,
  \ket{a} = \ket{a_1} \otimes \ket{ a_2} \cdots \ket{a_k}$ where $\kappa(a) = (a_1, a_2, \ldots, a_k)
  \in \F_2^k$ is the bijection introduced in Section~\ref{sec:finite-fields}
  corresponding to the basis $\{e_1,\ldots,e_k\}$. Observe that
  $\theta \otimes \theta \ket{\EPR_{2^k}} = \ket{\EPR_2}^{\ot k}$.

  Let $a \in \F_q$, and let $\kappa(a) = (a_1,\ldots,a_k) \in \F_2^k$.
  Then from~\eqref{eq:pauli-inversion-0}, we get
  \begin{equation}
    \label{eq:qudit-to-qubit-pauli-1}
    \begin{split}
      \tau^W_a
      & = \E_{b \in \F_q} (-1)^{\tr(a b)} \, \tau^W(b) \\
      & = \E_{b \in \F_q} (-1)^{\tr(\sum_j a_j e_j b)} \, \tau^W(b) \\
      & = \E_{b \in \F_q} (-1)^{\sum_j a_j b_j} \,
      \tau^W \left ( \sum_j b_j e_j \right) \;,
    \end{split}
  \end{equation}
  where $b = \sum_j b_j e_j$; since the basis $\{e_j \}$ is self-dual, we have
  that $b_j = \tr(b e_j)$. From~\eqref{eq:qudit-to-qubit-pauli-1} and
  the product relation in~\eqref{eq:pauli-product-power} we get that
  \begin{equation}
		\label{eq:qudit-to-qubit-pauli}
    \begin{split}
      \tau^W_a & = \E_{b_1,\, \ldots,\, b_k \in \F_2}\,
      \prod_{j=1}^k (-1)^{a_j b_j} \, \tau^W(b_j e_j) \\
      & = \prod_{j=1}^k \E_{b_j \in \F_2} (-1)^{a_j b_j} \, \tau^W(b_j e_j)\;,
    \end{split}
  \end{equation}
  where we have the used the fact that the expectation is over iid
  $b_1, \dots, b_k$ to take it inside the product in the second line.
  Next we claim that for all $c \in \F_2$, we have $\tau^W(c e_j) =
  \theta^\dagger \sigma^{W,j} (c) \theta$ where $\sigma^{W,j}(c) = \Id$ if $c =
  0$, and otherwise is the Pauli $W$ observable acting on the $j$-th qubit of
  $(\C^2)^{\otimes k}$. This can be verified by comparing the actions of both
  operators on the basis states of $\C^q$.

  Thus we obtain that the right-hand side of~\eqref{eq:qudit-to-qubit-pauli} is
  equal to
  \begin{align}
		\prod_{j=1}^k \E_{b_j \in \F_2} (-1)^{a_j b_j} \,
    \Big [ \theta^\dagger \sigma^{W,j}(b_j) \theta \Big ]
    & = \theta^\dagger \, \bigotimes_{j=1}^k
      \Big ( \E_{b_j \in \F_2} (-1)^{a_j b_j} \, \sigma^{W}(b_j) \Big) \theta \\
		& = \theta^\dagger \Big (\bigotimes_{j=1}^k \sigma^W_{b_j} \Big) \theta.
		\label{eq:qudit-to-qubit-pauli-2}
  \end{align}
  Define $\phi = \theta^{\otimes L}$. It is evident
  that~\eqref{eq:epr-q-to-epr-2} holds for this choice of $\phi$, and
  it remains to show~\eqref{eq:pauli-q-to-pauli-2}. The projector $\tau^W_u$ can be
  decomposed as the tensor product $\bigotimes_{i=1}^L \tau^{W}_{u_i}$
  where $\tau^{W}_{u_i}$ acts on the $i$-th factor of $(\C^q)^{\otimes L}$.
  Express each $u_i$ as $\sum_j u_{ij} e_j$ where $u_{ij} \in \F_2$. Then from
  Equation~\eqref{eq:qudit-to-qubit-pauli-2} we get that
  \begin{equation}
  	\tau^W_u = \bigotimes_{i=1}^L \tau^W_{u_i}
    = \phi^\dagger \left( \bigotimes_{i=1}^L
      \bigotimes_{j=1}^k \sigma^W_{u_{ij}} \right) \phi,
  \end{equation}
  which establishes Equation~\eqref{eq:pauli-q-to-pauli-2}. 
\end{proof}

We recall the Magic Square game of Mermin and Peres. It is a simple self-test for two EPR pairs, and it allows one to test that a pair of binary observables \emph{anticommutes}; both properties are used in the Pauli basis test. Here it is presented as a binary constraint satisfaction game. Throughout this section and the next, $\sigma^X$ and $\sigma^Z$ denote the single-qubit Pauli observables, with associated two-outcome projective measurements $\{\sigma^W_b\}_{b \in \F_2}$ for $W \in \{X,Z\}$.

\begin{definition}[The Magic Square game]\label{def:ms-game}
	\uses{def:game, def:graph-distribution}
	The Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ is the following two-player game. There are $9$ variables $x_1,\ldots,x_9$ taking values in $\F_2$, arranged in a $3 \times 3$ grid: the cell in row $r$ and column $c$ contains the variable $x_{3(r-1)+c}$. There are $6$ linear equations over these variables: for each of the three rows and each of the first two columns, the sum of the three variables in it equals $0$; for the third column, the sum of the three variables in it equals $1$.

	The question types are
	\begin{align*}
		\mathcal T^{\mathrm{mc}} &= \{\mathsf{Constraint}_i : i = 1,2,\ldots,6\}\;,\\
		\mathcal T^{\mathrm{mv}} &= \{\mathsf{Variable}_j : j = 1,2,\ldots,9\}\;,\\
		\mathcal T^{\mathrm{ms}} &= \mathcal T^{\mathrm{mc}} \cup \mathcal T^{\mathrm{mv}}\;,
	\end{align*}
	where $\mathsf{Constraint}_i$ for $i \in \{1,2,3\}$ denotes the constraint of row $i$ (with variables $x_{3(i-1)+1}, x_{3(i-1)+2}, x_{3(i-1)+3}$), $\mathsf{Constraint}_4$ and $\mathsf{Constraint}_5$ denote the constraints of the first two columns, and $\mathsf{Constraint}_6$ denotes the constraint of the third column (with variables $x_{i-3}, x_{i}, x_{i+3}$ for $\mathsf{Constraint}_i$, $i \in \{4,5,6\}$).

	The question distribution is as follows: the verifier samples $\mathsf{Constraint}_i$ uniformly from $\mathcal T^{\mathrm{mc}}$, then samples $\mathsf{Variable}_j$ uniformly among the three variables appearing in the row or column of $\mathsf{Constraint}_i$; one player, chosen uniformly at random, receives $\mathsf{Constraint}_i$ and the other receives $\mathsf{Variable}_j$. Equivalently, the verifier samples a uniformly random edge of the bipartite \emph{type graph} $G^{\mathrm{ms}}$ on vertex sets $\mathcal T^{\mathrm{mc}}$ and $\mathcal T^{\mathrm{mv}}$, whose edges are $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{3(i-1)+j}$ for $i,j \in \{1,2,3\}$ and $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{(i-3)+3(j-1)}$ for $i \in \{4,5,6\}$, $j \in \{1,2,3\}$ ($18$ edges in total, and no self-loops), and sends one endpoint to a uniformly random player and the other endpoint to the other player.

	The $\mathsf{Constraint}$ player answers with three bits $(\beta_{v_1}, \beta_{v_2}, \beta_{v_3}) \in \F_2^3$, where $(v_1,v_2,v_3)$ are the indices of the three variables of $\mathsf{Constraint}_i$; the $\mathsf{Variable}$ player answers with a single bit $\gamma \in \F_2$. The players win if and only if the $\mathsf{Constraint}$ player's answer satisfies the equation associated with $\mathsf{Constraint}_i$ and $\gamma = \beta_j$.
\end{definition}

The following theorem records the self-testing (rigidity) properties of the Magic Square game. It is used in the soundness analysis of the Pauli basis test to enforce anticommutation relations between certain pairs of observables.
With zero-based labels, the paper's variables $1$ and $5$ have labels $0$ and
$4$, respectively.

\begin{theorem}[Rigidity of the Magic Square game]\label{thm:ms-rigidity}
	\lean{MIPStarRE.QPBT.exists_ms_rigidity}
	\leanok
	\uses{def:ms-game, def:tensor-product-value, def:EPR, def:povm-distance}
	Let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy that succeeds in the Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ with probability $1-\eps$, where $\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$. Then there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot \hilb_{\mathrm B''}$, such that:
	\begin{enumerate}
		\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\sqrt\eps)$;
		\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$,
		\begin{align*}
			\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
			\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
		\end{align*}
		where each $\approx_{\sqrt\eps}$ holds with respect to the state $\ket{\mathrm{EPR}_2}^{\ot 2}_{\mathrm{A'B'}} \ot \ket{\mathrm{aux}}_{\mathrm{A''B''}}$ and the answer summation is over $b \in \{0,1\}$, and the approximation bounds carry implicit universal constants.
	\end{enumerate}
	As a consequence, letting $\tilde A^{\mathsf{Variable}_1} = \tilde A^{\mathsf{Variable}_1}_0 - \tilde A^{\mathsf{Variable}_1}_1$ and $\tilde A^{\mathsf{Variable}_5} = \tilde A^{\mathsf{Variable}_5}_0 - \tilde A^{\mathsf{Variable}_5}_1$ denote the associated observables, it holds that
	\begin{align*}
		\tilde A^{\mathsf{Variable}_1} \tilde A^{\mathsf{Variable}_5} \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} -\, \tilde A^{\mathsf{Variable}_5} \tilde A^{\mathsf{Variable}_1} \ot I_{\mathrm{B'B''}}\;,\\
		I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1} \tilde B^{\mathsf{Variable}_5} &\approx_{\sqrt\eps} -\, I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5} \tilde B^{\mathsf{Variable}_1}\;,
	\end{align*}
	where, for operators $M$, $N$ that are not POVM elements, the notation $M \approx_\delta N$ means $\bra{\psi} (M-N)^\dagger (M-N) \ket{\psi} \le O(\delta)$ with respect to the same state.
\end{theorem}
\begin{proof}
	This result is imported from Theorem~6.9 of~\cite{Coladangelo2017Robust}. There are two minor differences between their statement and the one given here. First, they state a robustness of $O(\eps)$, but measure the closeness of the actual and ideal states in trace norm; expressed as the Euclidean distance between $\phi_{\mathrm A} \ot \phi_{\mathrm B}\ket{\psi}$ and $\ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}}$, this becomes $O(\sqrt\eps)$. Second, their ideal observables for the $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ questions are $I \ot \sigma^Z$ and $\sigma^Z\sigma^X \ot \sigma^Z\sigma^X$; under a local change of basis these are equivalent to $\sigma^X \ot I$ and $\sigma^Z \ot I$, respectively.
\end{proof}

The converse construction shows that any pair of anticommuting binary observables yields a perfect strategy for the Magic Square game.

\begin{theorem}\label{thm:ms-from-ac}
